public static NVHcmTotalExperienceTmp populateTotalExperience(HcmWorker _worker)
{
    NVHcmTotalExperienceTmp totalExperienceTmp;
    HcmPersonProfessionalExperience pastExperience;
    while select pastExperience
        where pastExperience.Person == _worker.Person
    {
        totalExperienceTmp.EmployerName     = pastExperience.EmployerName;
        totalExperienceTmp.StartDate        = pastExperience.StartDate;
        totalExperienceTmp.EndDate          = pastExperience.EndDate;
        totalExperienceTmp.YearsOfService   = pastExperience.yearsOfService();
        totalExperienceTmp.insert();
    }

    HcmEmploymentView employmentView;
    while select employmentView
        where employmentView.Worker == _worker.RecId
    {
        HcmEmployment employment = HcmEmployment::find(employmentView.NVEmploymentRecId);
        totalExperienceTmp.EmployerName     = CompanyInfo::findRecId(employment.LegalEntity).name();
        totalExperienceTmp.StartDate        = DateTimeUtil::date(employment.ValidFrom);
        totalExperienceTmp.EndDate          = DateTimeUtil::date(employment.ValidTo);
        totalExperienceTmp.YearsOfService   = employment.yearsOfService();
        totalExperienceTmp.insert();
    }
    return totalExperienceTmp;
}

public static real getTotalExperience(HcmWorker _worker)
{
    real yearOfSerice = 0;
    HcmPersonProfessionalExperience pastExperience;
    while select pastExperience
        where pastExperience.Person == _worker.Person
    {
        yearOfSerice += pastExperience.yearsOfService();
    }

    HcmEmploymentView employmentView;
    while select employmentView
        where employmentView.Worker == _worker.RecId
    {
        HcmEmployment employment = HcmEmployment::find(employmentView.NVEmploymentRecId);
        yearOfSerice += employment.yearsOfService();
    }
    return yearOfSerice;
}
